package edu.carroll.cs341.web.form;

import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * Form class used to collect and validate a new password.
 * <p>
 * Ensures that both password entries contain between 8 and 30 characters,
 * do not contain spaces, and match each other.
 * <p>
 * <b>Sources Used:</b>
 * <ul>
 *   <li>ChatGPT – Assisted with generating Javadoc comments for this file
 *   in conjunction with Max Montowski.
 *   All comments were reviewed by the author. No code was generated by ChatGPT.</li>
 * </ul>
 */
public class EditPasswordForm {

    /**
     * First password entry; must contain between 8 and 30 characters
     * and cannot contain spaces.
     */
    @Size(min = 8, message = "New password must be at least 8 characters long")
    @Size(max = 30, message = "New password cannot be longer than 30 characters")
    @Pattern(regexp = "^\\S+$", message = "Password cannot contain spaces")
    private String password1;

    /**
     * Confirmation password entry; must contain between 8 and 30 characters
     * and cannot contain spaces.
     */
    @Size(min = 8, message = "New password must be at least 8 characters long")
    @Size(max = 30, message = "New password cannot be longer than 30 characters")
    @Pattern(regexp = "^\\S+$", message = "Password cannot contain spaces")
    private String password2;

    /**
     * Retrieves the first password entry.
     *
     * @return the first password entry
     */
    public String getPassword1() {
        return password1;
    }

    /**
     * Updates the first password entry.
     *
     * @param password1 the first password entry to set
     */
    public void setPassword1(String password1) {
        this.password1 = password1;
    }

    /**
     * Retrieves the confirmation password entry.
     *
     * @return the confirmation password entry
     */
    public String getPassword2() {
        return password2;
    }

    /**
     * Updates the confirmation password entry.
     *
     * @param password2 the confirmation password entry to set
     */
    public void setPassword2(String password2) {
        this.password2 = password2;
    }

    /**
     * Checks whether the two password entries match.
     *
     * @return true if both passwords match; false otherwise
     */
    @AssertTrue(message = "Passwords must match")
    public boolean isPasswordMatching() {
        if (password1 == null || password2 == null) {
            return true;
        }

        return password1.equals(password2);
    }
}
